-- AI: N117 initial-only department/calendar. ONE append migration; no backfill.
begin;
set local lock_timeout='10s';
do $guard$ begin
  if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='rakeezx.complete_account_profile(text,text,text,text)'::regprocedure) is distinct from 'e4eccce8c5a4f0486e872a4a56f64ce8' then raise exception 'N117_SERVICE_PREIMAGE_DRIFT: rakeezx.complete_account_profile(text,text,text,text)'; end if;
  if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='rakeezx.provision_account_workspace(jsonb)'::regprocedure) is distinct from 'a641c556c736f72b63d1e0cb203e1e1e' then raise exception 'N117_SERVICE_PREIMAGE_DRIFT: rakeezx.provision_account_workspace(jsonb)'; end if;
  if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='rakeezx.n58_guard_calendar_contract()'::regprocedure) is distinct from '6fc9fcdf35f78d0ae295fe61a833f70d' then raise exception 'N117_SERVICE_PREIMAGE_DRIFT: rakeezx.n58_guard_calendar_contract()'; end if;
  if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='rakeezx.guard_account_provisioning_state()'::regprocedure) is distinct from 'fb619469245bc4f6c745f92e8cc101b5' then raise exception 'N117_SERVICE_PREIMAGE_DRIFT: rakeezx.guard_account_provisioning_state()'; end if;
  if (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid='rakeezx.account_provisioning_foundation_complete(uuid)'::regprocedure) is distinct from 'fe9642afe21ddeab07c7538c57171c1e' then raise exception 'N117_SERVICE_PREIMAGE_DRIFT: rakeezx.account_provisioning_foundation_complete(uuid)'; end if;
  if to_regprocedure('rakeezx.complete_account_profile_before_n117(text,text,text,text)') is not null or to_regprocedure('rakeezx.provision_account_workspace_before_n117(jsonb)') is not null then raise exception 'N117_ALREADY_APPLIED'; end if;
end $guard$;
-- No new tables/roles, Auth or RLS change. Existing private implementations
-- retain receipt recovery and four-argument existing-client compatibility.
alter function rakeezx.complete_account_profile(text,text,text,text) rename to complete_account_profile_before_n117;
revoke all on function rakeezx.complete_account_profile_before_n117(text,text,text,text) from public,anon,authenticated;
alter function rakeezx.provision_account_workspace(jsonb) rename to provision_account_workspace_before_n117;
revoke all on function rakeezx.provision_account_workspace_before_n117(jsonb) from public,anon,authenticated;

create function rakeezx.complete_account_profile(p_teacher_name text,p_phone text,p_teacher_form text,p_school_name text default null,p_education_department text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_owner uuid:=auth.uid(); v_profile rakeezx.profile%rowtype; v_department text;
begin
  if v_owner is null then raise exception using errcode='42501',message='Authentication required'; end if;
  perform rakeezx.lock_student_lifecycle(v_owner);
  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;
  if not found then raise exception using errcode='42501',message='N117_PROFILE_CHECKPOINT_REQUIRED'; end if;
  if v_profile.provisioning_state in ('PROFILE_REQUIRED','PROVISIONING_REQUIRED','PROVISIONING') then
    v_department:=coalesce(p_education_department,v_profile.education_department);
    if v_department is null or not exists(select 1 from rakeezx.education_departments where name=v_department) then
      raise exception using errcode='22023',message='N117_DEPARTMENT_REQUIRED'; end if;
    if v_profile.provisioning_state='PROVISIONING' and v_profile.education_department is distinct from v_department then
      raise exception using errcode='22023',message='N117_INITIAL_DEPARTMENT_LOCKED'; end if;
    update rakeezx.profile set education_department=v_department where owner_id=v_owner;
  elsif p_education_department is not null and p_education_department is distinct from v_profile.education_department then
    raise exception using errcode='22023',message='N117_EXISTING_ACCOUNT_METADATA_ONLY';
  end if;
  perform rakeezx.complete_account_profile_before_n117(p_teacher_name,p_phone,p_teacher_form,p_school_name);
  return rakeezx.account_contract();
end $$;

create or replace function rakeezx.provision_account_workspace(p_defaults jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_owner uuid := auth.uid(); v_profile rakeezx.profile%rowtype;
  v_year jsonb; v_calendar jsonb; v_subject jsonb; v_row jsonb;
  v_hash text; v_manifest jsonb; v_preset text; v_expected jsonb; v_normalized jsonb; v_key text;
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  perform rakeezx.lock_student_lifecycle(v_owner);
  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;
  if v_profile.owner_id is null or v_profile.provisioning_state not in ('PROVISIONING','READY') or
      v_profile.profile_status <> 'READY' then
    raise exception using errcode='42501', message='Account provisioning has not begun';
  end if;
  if v_profile.provisioning_state='READY' and
      rakeezx.account_provisioning_foundation_complete(v_owner) then
    return pg_catalog.jsonb_build_object('contract',rakeezx.account_contract(),
      'snapshot',rakeezx.account_provisioning_snapshot());
  end if;
  if not exists(select 1 from rakeezx.account_access_grants where owner_id=v_owner and
      grant_type='beta_full' and status='active' and (expires_at is null or expires_at > now())) then
    raise exception using errcode='42501', message='Beta access is required';
  end if;
  -- READY repair is kept behind the original immutable receipt/hash rules.
  -- Initial provisioning must never retag a previously committed foundation.
  if v_profile.provisioning_state='READY' then
    return rakeezx.provision_account_workspace_before_n117(p_defaults);
  end if;
  if v_profile.education_department is null or not exists(select 1 from rakeezx.education_departments where name=v_profile.education_department) then
    raise exception using errcode='22023', message='N117_DEPARTMENT_REQUIRED'; end if;
  v_preset:=case when v_profile.education_department in ('الإدارة العامة للتعليم بمحافظة جدة','الإدارة العامة للتعليم بمنطقة المدينة المنورة','إدارة التعليم بمحافظة الطائف','الإدارة العامة للتعليم بمنطقة مكة المكرمة') then 'sa-western-1448-1449' else 'sa-general-1448-1449' end;
  v_expected:=case when v_preset='sa-western-1448-1449' then $western${"years":[{"id":"y:1448-1449","deleted":false,"label":"1448–1449 هـ","hijriStart":1448,"hijriEnd":1449,"order":1448,"status":"active","calendarPresetId":"sa-western-1448-1449","calendarRegion":"مكة المكرمة • المدينة المنورة • جدة • الطائف","gregorianLabel":"2026–2027 م","startDate":"2026-08-30","endOfYearVacationStart":"2027-07-01","nextAcademicYearStart":"2027-08-29"}],"calendars":[{"id":"cal:y:1448-1449:preset:sa-western-1448-1449","deleted":false,"yearId":"y:1448-1449","source":"preset:sa-western-1448-1449","label":"التقويم المعتمد · 1448–1449 هـ · مكة المكرمة • المدينة المنورة • جدة • الطائف","presetId":"sa-western-1448-1449"}],"terms":[{"id":"tm:y:1448-1449:1","deleted":false,"yearId":"y:1448-1449","name":"الفصل الدراسي الأول","index":1,"startDate":"2026-08-30","endDate":"2027-01-07","status":"active","calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449"},{"id":"tm:y:1448-1449:2","deleted":false,"yearId":"y:1448-1449","name":"الفصل الدراسي الثاني","index":2,"startDate":"2027-01-17","endDate":"2027-07-01","status":"upcoming","calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449"}],"calendarDays":[{"id":"cd:cal:y:1448-1449:preset:sa-western-1448-1449:2026-09-23","deleted":false,"calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449","date":"2026-09-23","kind":"national","label":"إجازة اليوم الوطني","presetId":"sa-western-1448-1449","rangeId":"sa-western-1448-1449:2026-09-23","rangeStart":"2026-09-23","rangeEnd":"2026-09-26"},{"id":"cd:cal:y:1448-1449:preset:sa-western-1448-1449:2026-09-24","deleted":false,"calendarId":"cal:y:1448-1449:preset:sa-western-1448-1449","date":"2026-09-24","kind":"national","label":"إجازة اليوم الوطني","presetId":"sa-western-1448-1449","rangeId":"sa-western-1448-1449:2026-09-23","rangeStart":"2026-09-23","rangeEnd":"2026-09-26"},{"id":"cd:cal:y:1448-1449:preset:sa-western-1448-1449:2026-09-25","deleted":false,"calendarId":"cal:y:1448-1449:preset:sa-western